import { BrowserRouter, Routes, Route, useParams } from 'react-router-dom';
import { i18n } from '_/i18n';
import { gtm } from '_/gtm';
import { applyParamsToUrl } from '_/url/applyParams';
import { _ } from '_/types';
import { Layout } from '@/support/Layout';
import { UpdatePathname, pathname } from './pathname';
import { routes } from './routes';

const appTitle = document.title;

/** Router context. */
export const Context = React.createContext({
  /** Current route locales. */
  locales: {} as (typeof routes)[number]['locales'],
  /** Current route parameters. */
  params: {} as _.Dict,
});

export const Support_Router: React.FC = () => (
  <BrowserRouter>
    <UpdatePathname />
    <Routes>
      {routes.map(({ Screen, language, locales, meta, pathnameFr }, index) => {
        const { pathname, params, goto, title } = meta;
        const withParams = /:/.test(pathname);
        const status = pathname === '*' ? 404 : 200;
        return (
          <Route
            key={index}
            path={meta.pathname}
            Component={(): React.Node => {
              const pathnameParams = withParams && useParams();
              const allParams = { ...params, ...pathnameParams };
              if (language !== 'any' && language !== i18n.language) {
                void i18n.changeLanguage(language);
              }
              document.title = title ? `${title} • ${appTitle}` : appTitle;
              document.head.setAttribute('data-status', String(status));

              React.useEffect(pageView, [location.pathname]);

              function pageView(): void {
                gtm.pageView(applyParamsToUrl(pathnameFr, pathnameParams));
              }

              return (
                <Context.Provider value={{ locales, params: allParams }}>
                  <Layout Screen={Screen} goto={goto} />
                </Context.Provider>
              );
            }}
          />
        );
      })}
    </Routes>
  </BrowserRouter>
);

export const Router = Object.assign(Support_Router, { Context, pathname });
