import { BarLoader } from '@/atoms/BarLoader';
import { Logo } from '@/atoms/Logo';
import { useTimeoutPromiseManager } from '@/hooks/useTimeoutPromiseManager';

import styles from './styles.scss';

export const Molecule_LoadingOverlay: React.FC<Props> = ({ visible }) => {
  const [display, setDisplay] = React.useState(true);
  const displayTimeoutManager = useTimeoutPromiseManager({ delay: 350 });

  React.useEffect(updateDisplay, [display, visible]);

  function hide(): void {
    setDisplay(false);
  }

  function updateDisplay(): void {
    document.body.style.height = display ? '100%' : '';
    if (display && !visible) {
      void displayTimeoutManager.restart()?.then(hide);
    }
  }

  return display ? (
    <div classNames={[styles.root, visible && styles.visible]}>
      <div className={styles.content}>
        <Logo className={styles.logo} />
        <div className={styles.loaderContainer}>
          <BarLoader className={styles.loader} />
        </div>
      </div>
    </div>
  ) : null;
};

export const LoadingOverlay = Molecule_LoadingOverlay;
