import { _ } from '_/types';
import { screens } from '@/screens';

const languages = ['any', 'en', 'fr'] as const;

export const routes = screens
  .map((Screen) =>
    [Screen.route, ...(Screen.subroutes ?? [])].map((locales) =>
      languages.map((language) => {
        const meta = locales?.[language];
        if (meta) {
          const pathnameFr = locales?.fr?.pathname ?? locales?.any?.pathname ?? meta.pathname;
          return { Screen, language, locales, meta, pathnameFr };
        } else {
          return null;
        }
      }),
    ),
  )
  .flat(2)
  .filter(_.isTruthy);

const pathnames: _.Dict<(typeof routes)[number]['meta']> = {};

routes.forEach(({ meta }) => {
  if (pathnames[meta.pathname]) {
    console.warn('Already registered:', meta.pathname);
  } else {
    pathnames[meta.pathname] = meta;
  }
});
