import { Link as LegacyLink } from 'react-router-dom';
import { useTranslation } from '_/i18n';
import { applyParamsToUrl } from '_/url/applyParams';
import { useScroll } from '@/support/Layout/useScroll';
import { screens } from '@/screens';

export const Atom_Link = <To extends Link.Props.To>(props: Link.Props<To>): React.Node => {
  const { onClick, params, to, ...linkProps } = props;
  const scroll = useScroll();
  const [, i18n] = useTranslation();
  let toPathname = '';
  function maybeResetScroll(...args: OnClickParameters): void {
    if (!args[0].isDefaultPrevented()) {
      onClick?.(...args);
      if (!args[0].isDefaultPrevented() && toPathname === location.pathname) {
        args[0].preventDefault();
        scroll.reset();
      }
    }
  }
  if (typeof to === 'string') {
    const {
      preventScrollReset,
      relative,
      reloadDocument,
      replace,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      state,
      target = '_blank',
      ...attrs
    } = props;
    toPathname = applyParamsToUrl(to, params);
    return <a href={toPathname} target={target} {...attrs} />;
  } else {
    const route = to.route ?? to;
    const meta = route.any ?? route[i18n.lang];
    toPathname = applyParamsToUrl(meta.pathname, params);
    return <LegacyLink to={toPathname} onClick={maybeResetScroll} {...linkProps} />;
  }
};

export const Link = Object.assign(Atom_Link, screens);
