import { z } from 'zod';
import { stringifyIssues } from '_/zod/stringifyIssues';
import { confSchema, envSchema } from './schema';

function confError(cause: unknown, mode: 'error' | 'warn', label: string, root = ''): void {
  if (cause instanceof z.ZodError) {
    const NODE_ENV = process.env.NODE_ENV;
    const env = typeof NODE_ENV === 'string' ? JSON.stringify(NODE_ENV) : String(NODE_ENV);
    const issues = stringifyIssues(cause, `process.env${root}`);
    const message = [`${label}:`, `process.env.NODE_ENV: ${env}`, ...issues];
    console[mode](message.join('\n  '));
  } else {
    throw cause;
  }
}

export function parse(): Conf | null {
  const env = { ...process.env, NODE_ENV: process.env.NODE_ENV };
  try {
    const conf = envSchema.parse(env).CONF;
    try {
      confSchema.strict().parse(conf);
    } catch (cause) {
      confError(cause, 'warn', 'Configuration warning', '.CONF');
    }
    return conf;
  } catch (cause) {
    confError(cause, 'error', 'Invalid configuration');
  }
  return null;
}
