import { arrayGen } from '_/array/gen';
import { pad as padNumber } from '_/number/pad';
import { Link } from '@/atoms/Link';
import { Project } from '@/screens/Project';
import { ProjectViewer } from '@/screens/Project/Viewer';

import styles from './styles.scss';

const BASEPATH = '/img/projects/claire-duchamp';
const EXT = 'thumbnail.jpg';

export const Screen_Project_ThumbnailGrid: React.FC<Props> = (props) => {
  const viewer = React.useRef<ProjectViewer.Handle>(null);

  function view(photo: number): (event: React.MouseEvent<HTMLAnchorElement>) => void {
    function openViewer(event: React.MouseEvent<HTMLAnchorElement>): void {
      event.preventDefault();
      viewer.current?.open(photo);
    }
    return openViewer;
  }

  const { photoIndex, project, ...divAttrs } = props;
  const { id, pictures } = project;
  const { basename, count } = pictures;
  const path = `${BASEPATH}-${basename}`;
  const pad = padNumber.accordingTo(count);
  const imgs = arrayGen(count, (index) => `${path}-${pad(index + 1)}-${EXT}`);

  return (
    <div classNames={styles.root} {...divAttrs}>
      {imgs.map((src, index) => {
        const photo = String(index + 1);
        return (
          <Link key={index} to={Project[id]} params={{ photo }} onClick={view(index + 1)}>
            <img src={src} className={styles.thumbnail} />
          </Link>
        );
      })}
      <ProjectViewer ref={viewer} photoIndex={photoIndex} project={project} />
    </div>
  );
};

export const ProjectThumbnailGrid = Screen_Project_ThumbnailGrid;
