import { useNavigate, useParams } from 'react-router-dom';
import { i18n, Language } from '_/i18n';
import { Context } from '@/support/Router';
import { applyParamsToUrl } from '@/utils/url/applyParams';

export function useChangeLanguage(
  language = i18n.fallbackLng,
): [(language?: Language) => void, typeof i18n] {
  const { locales } = React.useContext(Context);
  const navigate = useNavigate();
  const params = useParams();
  function changeLanguage(innerLanguage = language): void {
    if (innerLanguage !== i18n.language) {
      const meta = locales[innerLanguage];
      const pathname = meta && applyParamsToUrl(meta.pathname, params);
      if (pathname && pathname !== location.pathname) {
        navigate(pathname);
      } else {
        void i18n.changeLanguage(innerLanguage);
      }
    }
  }
  return [changeLanguage, i18n];
}
